const fs=require('node:fs');
const d='storage/app/ui-audit';
const files=fs.readdirSync(d).filter(f=>/^results-(?:readback-)?\d+-\d+\.json$/.test(f)).sort((a,b)=>fs.statSync(`${d}/${a}`).mtimeMs-fs.statSync(`${d}/${b}`).mtimeMs);
const map=new Map();for(const file of files)for(const row of JSON.parse(fs.readFileSync(`${d}/${file}`)))map.set(row.path,row);
const results=[...map.values()];fs.writeFileSync(`${d}/results.json`,JSON.stringify(results,null,2));
const findings=[];
function add(severity,status,title,paths,steps,evidence,expected,source){findings.push({id:`UI-${String(findings.length+1).padStart(2,'0')}`,severity,status,title,paths,steps,evidence,expected,source});}
add('High','Reproduced','Mobile header hamburger does nothing',['/clients/9/edit'],'At 390px width click the hamburger in the light header.','It targets #navbar-menu, which does not exist. The sidebar hamburger works; the header hamburger does not.','Use one working navigation control.','resources/views/scaffold-interface/layouts/tabler-header.blade.php:15');
findings[0].status = 'Fixed; browser-verified 2026-10-16';
findings[0].evidence += ' Resolution: the header now targets #sidebar-menu, including aria-controls. tests/Browser/mobile-navigation.cjs passed header/sidebar open and close, synchronized aria-expanded, tablet navigation at 820px and desktop navigation at 1440px. Original observation above is retained as audit history.';
add('Medium','Reproduced','Two navigation bars consume excessive mobile space',['/clients/9/edit','/hotel/1/edit'],'Open an authenticated page at 390px width.','Both TMS brands and both hamburgers render. Measured heights: 100px sidebar bar plus 85px header bar.','Combine mobile navigation into one compact bar.','resources/views/scaffold-interface/layouts/tabler-sidebar.blade.php:8');
findings[1].status = 'Fixed; browser-verified 2026-10-16';
findings[1].evidence += ' Resolution: removed the duplicate sidebar toggle, restricted its brand to desktop, eliminated the collapsed sidebar bar below 992px, and made the compact header toggle available through the tablet breakpoint. tests/Browser/mobile-navigation.cjs passed one visible brand/control and a header no taller than 72px at 320/390/820px, navigation open/close, the user dropdown, and the desktop sidebar. Original observation above is retained as audit history.';
add('Medium','Reproduced','Notifications and message shortcuts disappear on phones',['/clients/9/edit'],'Compare header actions at desktop and phone widths.','Both Show notifications and Show messages triggers become hidden; no replacement exists in the mobile sidebar placeholder.','Expose equivalent mobile shortcuts.','resources/views/scaffold-interface/layouts/tabler-header.blade.php:26');
findings[2].status = 'Fixed; browser-verified 2026-10-16';
findings[2].evidence += ' Resolution: notification and message shortcuts remain visible on phones; phone dropdowns fit within viewport gutters and scroll when tall. tests/Browser/mobile-navigation.cjs passed visibility, dropdown opening, visible links, viewport bounds and Escape dismissal at 320/390/820/1440px, plus compact navigation and the user menu. Notification loading and message actions retain their existing behavior; the read-only browser test blocks data requests and does not test live notification contents or submit actions. Original observation above is retained as audit history.';
add('High','Reproduced','Chat Add User Chat / Add Chat popup does not open',['/chat/main'],'Click Add User Chat; do not select a user or submit.','No visible modal appears. Buttons use data-toggle/data-target; the shared loader fills .AjaxisModal but does not open it under Bootstrap 5.','Open the intended dialog with Bootstrap 5-compatible wiring.','resources/views/chats/main.blade.php:20; public/js/AjaxisBootstrap.js:28');
findings[3].status = 'Fixed; browser-verified 2026-10-17';
findings[3].evidence += ' Resolution: chat actions now use buttons; their AJAX handler opens the Bootstrap modal, displays loading/error states, reuses the existing dialog without nested wrappers, adds a close button, restores trigger focus and ignores stale responses. tests/Browser/chat-dialogs.cjs passed both real dialog GETs at desktop/phone widths, viewport bounds, close/Escape, simulated HTTP 500 and successful retry. The browser permits only the chat page, two read-only dialog endpoints and static assets; no chat was created, selected or deleted. Original observation above is retained as audit history.';
add('High','Reproduced','Activities table enhancement fails',['/activities'],'Open Activities and inspect its filtering/export controls.','JavaScript throws $(...).DataTable is not a function. The layout does not load DataTables; intended column filters and DataTables export controls are not initialized.','Load the matching table plugin or use the existing native table controls consistently.','resources/views/activities/index.blade.php:57');
findings[4].status = 'Fixed; browser-verified 2026-10-17';
findings[4].evidence += ' Resolution: replaced the obsolete DataTables initializer with native pagination/sorting, labeled global search, combined column filters, page-size selection and CSV/Excel/PDF exports using local libraries. Export includes all matching pages and excludes action controls. The shared paginator accepts optional column filters while retaining its existing default behavior. tests/Browser/activities-table.cjs passed initialization on the real Activities page, no-results handling, combined searches, sorting, pagination and all three downloads using browser-memory fixtures; CSV and Excel contents were checked across pages. No activity records were created or changed. Original observation above is retained as audit history.';
add('Medium','Reproduced','Task time picker initialization fails',['/task/create','/task/133/edit'],'Open either task form.','JavaScript throws $(...).timepicker is not a function. The initializer stops at this point.','Initialize an available time picker or provide a working native control without exceptions.','resources/views/task/create.blade.php:289; resources/views/task/edit.blade.php:331');
findings[5].status = 'Fixed; browser-verified 2026-10-17';
findings[5].evidence += ' Resolution: both forms use required native time inputs with one-second precision instead of the missing jQuery timepicker. Create retains the 18:00 default; edit retains stored time and both honor validation old input. tests/Browser/task-time.cjs passed both actual pages without JavaScript errors, initial values, midnight/end-of-day/seconds, required/invalid input, serialized time values and the assignment guard that previously failed to register. No tasks were saved. This verifies browser behavior, not changes to server-side validation. Original observation above is retained as audit history.';
add('High','Reproduced','Flights list opens an error screen',['/flights'],'Open the flights list.','HTTP 500: route flights.show requires flight but action URLs pass id.','Render the list and its row actions successfully.','app/Http/Controllers/FlightController.php:53');
findings[6].status = 'Fixed; browser-verified 2026-10-17';
findings[6].evidence += ' Resolution: controller action URLs use the resource flight parameter; the shared action component has a Flights-specific route branch so show/edit URLs and the existing GET deletion route resolve correctly. Removed the server-pagination footer that called paginator methods on the controller collection; native client pagination remains in use. tests/Browser/flights-list.cjs passed HTTP 200, all three existing flight rows and their action URL targets, search/reset, and phone/desktop rendering. No row actions were opened or records changed. Detail/edit Google lookup failures remain separately tracked in UI-08. Original observation above is retained as audit history.';
add('High','Reproduced; configuration-dependent','Flight detail/edit fail when Google Places rejects the lookup',['/flights/1','/flights/1/edit'],'Open existing flight 1.','HTTP 500 with Google REQUEST_DENIED rather than a usable record page. This is an integration/configuration dependency, not a CSS defect.','Display stored record data with a useful service-unavailable fallback.','app/Http/Controllers/FlightController.php');
findings[7].status = 'Fixed; browser-verified 2026-10-17';
findings[7].evidence += ' Resolution: corrected the Google Places exception namespace and catch expected API/network failures, while preserving successful lookups. Flights show/edit display a warning for unavailable saved locations; edit retains the stored place ID independently of the external response. GooglePlacesFallbackTest passed 3 tests/9 assertions in isolated SQLite memory for success, missing location, denied request and network failure without deleting saved locations. tests/Browser/flight-details.cjs passed both real pages with HTTP 200 during lookup failure, fallback messages and retained edit location data; no forms were submitted. This adds graceful fallback and does not repair Google credentials or prove live map availability. Original observation above is retained as audit history.';
add('High','Reproduced','New Tour Package button leads to a broken form URL',['/tour_package','/tour_package/create'],'Click New on the package list.','The form navigates to /tour_package/create without the tour-day ID required by the controller; HTTP 500.','Request the required context or link to a valid contextual create route.','resources/views/tour_package/index.blade.php:13');
findings[8].status = 'Fixed; browser-verified 2026-10-17';
findings[8].evidence += ' Resolution: the context-free create route displays a labeled required tour-day selector, listing days belonging to active tours, and redirects the selected day to the existing contextual create form. An empty-state message explains when no days are available; malformed IDs return 422 and nonexistent/ineligible days return 404. Corrected the service loader reference from nonexistent App\\Cruise to the existing App\\Cruises model, which otherwise blocked the contextual form. tests/Browser/package-create.cjs passed the actual New button, required selection, contextual HTTP 200/form rendering, malformed IDs and nonexistent ID. No package save was submitted; package creation persistence is outside this check. Original observation above is retained as audit history.';
add('High','Reproduced; record-specific','An existing package edit fails with a missing parent tour',['/tour_package/1/edit'],'Open edit for package 1.','HTTP 500: departure_date is read on a null parent in the edit view. This was reproduced for this legacy record; it is not a claim that every package fails.','Handle missing parent data and keep the edit page usable.','resources/views/tour_package/edit.blade.php');
findings[9].status = 'Handled; read-only fallback verified 2026-10-17';
findings[9].evidence += ' Resolution: orphaned packages display stored details with a clear missing-tour warning and a link back to packages instead of rendering a broken edit form. Editing remains disabled until the correct tour association is restored; no parent is invented or assigned. Direct updates without a parent return 409 before writes. tests/Browser/package-missing-tour.cjs passed package 1 at phone/desktop widths, details/warning/back link, absence of edit form, and nonexistent-record 404. OrphanPackageEditTest passed 1 isolated test/3 assertions for update rejection and unchanged data. No existing records were changed. Original observation above is retained as audit history.';
add('High','Reproduced','Guest list index cannot render',['/guestlist'],'Open the guest-list resource list.','HTTP 500: the view refers to undefined route quotation.data.','Render guest lists using an existing endpoint.','resources/views/guest_list/index.blade.php:58');
