add('Medium','Reproduced; direct resource routes','User, role and permission detail routes have no show action',['/users/1','/roles/1','/permissions/1'],'Open the detail URLs directly.','All return HTTP 500 because show() does not exist. Lists and edit forms are separate and can still load.','Implement details or remove unsupported view actions/routes.','app/Http/Controllers/ScaffoldInterface/UserController.php; app/Http/Controllers/ScaffoldInterface/RoleController.php; app/Http/Controllers/ScaffoldInterface/PermissionController.php');
