add('Medium','Reproduced / protected preview','Some exposed pages return an empty screen',['/quotation/2','/comparison','/comparison/create'],'Open quotation detail, or inspect protected Comparison previews.','Quotation detail has HTTP 200 with no content. Comparison index/create also return empty HTTP 200 in the preview.','Show meaningful content or an explicit unsupported/empty-state page.','app/Http/Controllers/QuotationController.php; app/Http/Controllers/ComparisonController.php');
