const q=value=>'"'+String(value??'').replaceAll('"','""')+'"';
const csv=(headers,rows)=>'\uFEFF'+[headers,...rows].map(row=>row.map(q).join(',')).join('\r\n');
fs.writeFileSync('docs/ui-audit-findings-2026-10-16.csv',csv(['ID','Severity','Confidence','Issue','Pages','Reproduce','Evidence','Expected','Source'],findings.map(f=>[f.id,f.severity,f.status,f.title,f.paths.join('; '),f.steps,f.evidence,f.expected,f.source])));
fs.writeFileSync(`${d}/coverage.csv`,csv(['Path','Status','Final path','Desktop inspected','Phone inspected','JS errors','Recheck milliseconds'],results.map(r=>[r.path,r.status??'timeout',r.finalPath,r.viewports.some(v=>v.width===1440),r.viewports.some(v=>v.width===390),r.errors.join('; '),r.milliseconds??''])));
const instances=[];
for(const row of results.filter(r=>r.status===200))for(const key of ['duplicateIds','unlabelledFields','orphanLabels','unnamedButtons','nestedInteractive','brokenImages'])for(const item of row.viewports[0]?.[key]??[])instances.push([row.path,key,JSON.stringify(item)]);
fs.writeFileSync('docs/ui-audit-dom-instances-2026-10-16.csv',csv(['Path','Screening category','Observed element'],instances));
const counts={};for(const row of results)counts[row.status??'timeout']=(counts[row.status??'timeout']||0)+1;
const severities={};for(const finding of findings)severities[finding.severity]=(severities[finding.severity]||0)+1;
const sourceResults=JSON.parse(fs.readFileSync(`${d}/source-results.json`));
const previewResults=JSON.parse(fs.readFileSync(`${d}/results-preview-0-20.json`));
const summary={urls:results.length,http:counts,desktop:results.filter(r=>r.viewports.some(v=>v.width===1440)).length,phone:results.filter(r=>r.viewports.some(v=>v.width===390)).length,protectedPreviews:previewResults.length,templates:sourceResults.templateCount,findings:findings.length,severities,instanceRows:instances.length};
fs.writeFileSync(`${d}/summary.json`,JSON.stringify(summary,null,2));
let markdown=`# Project UI audit — October 16, 2026\n\n${findings.length} consolidated findings: ${severities.High} high, ${severities.Medium} medium and ${severities.Low} low priority. Confidence is listed for each finding; conditional/network-dependent and source-review candidates are not presented as universally reproduced defects.\n\n`;
markdown+=`## Coverage and limits\n\n- ${summary.urls} distinct GET URLs inspected; ${summary.desktop} desktop render checks at 1440px and ${summary.phone} phone render checks at 390px. The inventory includes a small number of direct resource/AJAX routes, whose failures are distinguished from visible navigation defects.\n- ${summary.protectedPreviews} additional protected layouts previewed in a local, non-persisted permission context. This reviews markup/layout and is not proof the current account can access or operate those screens. No account permissions were changed.\n- ${summary.templates} Blade templates statically scanned for asset references and legacy interaction attributes; shared layouts and implicated views manually reviewed. This is not a claim that every dormant template was manually exercised.\n- Final GET results: ${Object.entries(counts).map(([status,n])=>`${n} HTTP ${status}`).join(', ')}. HTTP 403 results are account-access restrictions, not automatically UI bugs.\n- No forms were submitted to existing records, no notifications or emails were sent, and no UI fixes were applied. Existing application edits were preserved.\n- CDN failures are explicitly conditional: external assets were unavailable in the audit environment. Portal authenticated screens, live mailbox/Google/webmail flows, successful saves, destructive actions, every modal state, all browsers and every viewport size are outside this read-only audit.\n- The GET tour-view side effect is documented in UI-41. Two exact, unchanged empty rows attributable to the audit were archived and removed. A concurrent browser edit to client 10 was left intact. No other database-table difference remained in the preservation check.\n\n`;
markdown+='## Complete consolidated list\n\n| ID | Priority | Finding | Confidence | Example page |\n| --- | --- | --- | --- | --- |\n';
for(const f of findings)markdown+=`| ${f.id} | ${f.severity} | [${f.title}](#${f.id.toLowerCase()}) | ${f.status} | ${f.paths.map(p=>p.startsWith('/')?'['+p+'](http://127.0.0.1:8010'+p+')':p).join(', ')} |\n`;
markdown+='\n## Reproduction and evidence\n';
for(const f of findings){
    markdown+=`\n<a id="${f.id.toLowerCase()}"></a>\n\n### ${f.id} — ${f.title}\n\n**${f.severity}; ${f.status}.**\n\n- Reproduce: ${f.steps}\n- Observed: ${f.evidence}\n- Expected: ${f.expected}\n- Source: ${f.source.split('; ').map(s=>'`'+s+'`').join(', ')}\n`;
    const row=f.paths.map(p=>map.get(p)).find(Boolean);const screenshot=row?.viewports.find(v=>v.screenshot)?.screenshot;
    if(screenshot)markdown+=`- Screenshot: [${screenshot}](/F:/dev-eetstravel/${d}/screenshots/${screenshot})\n`;
}
markdown+='\n## Follow-up observations, not confirmed additional defects\n\n- `/tour/3` took 7.76 seconds for a direct HTTP response on recheck. Earlier browser timeouts were transient; subsequent HTTP responses succeeded. Repeat timing under controlled load before assigning a performance defect.\n- `/supplier_show` without required search context returned 500; `/reporting_supplier_show` without a service filter returned 422. These are AJAX/helper endpoints, not normal navigation pages, and the bare-URL probes are not counted as separate UI defects.\n- The first offer-form probe used the wrong resource ID. The valid contextual `/tour_package/hotel_offers/531/create` returned 200, so the invalid-ID probe is not reported as a broken offer-create flow.\n- `/tour_package/531/edit` and `/comparison/1` returned 404 for the selected context. A 404 alone was not counted as a UI defect.\n- Direct `/quotation/create` returned an argument error, but the quotation list’s New action correctly goes through `/tour/create?is_quotation=1`. The unsupported direct route is in raw coverage, not an additional confirmed New-button defect.\n\n';
markdown+='## Detailed artifacts\n\n- [Findings spreadsheet](/F:/dev-eetstravel/docs/ui-audit-findings-2026-10-16.csv)\n- [Per-page DOM screening instances](/F:/dev-eetstravel/docs/ui-audit-dom-instances-2026-10-16.csv) — includes candidates and duplicate/shared occurrences, not additional consolidated defect counts.\n- [URL coverage and statuses](/F:/dev-eetstravel/storage/app/ui-audit/coverage.csv)\n- [Raw browser results](/F:/dev-eetstravel/storage/app/ui-audit/results.json)\n- [Protected preview results](/F:/dev-eetstravel/storage/app/ui-audit/results-preview-0-20.json)\n- [Interaction evidence](/F:/dev-eetstravel/storage/app/ui-audit/interaction-results.json)\n- [Preservation check](/F:/dev-eetstravel/storage/app/ui-audit/preservation.json)\n\nRecommended order: repair blocked screens and dialogs first, then mobile navigation, labels/keyboard behavior and encoding, then cosmetic consistency and remaining conditional/source-only findings.\n';
fs.writeFileSync('docs/ui-audit-2026-10-16.md',markdown);
